# frozen_string_literal: true

module Hue
  module Sdk
    # Typed values of the CLIP v2 API, generated by schema/generate.rb from the classes of the Hue app:
    # a response class per object the bridge reports, and the request classes the app sends to update
    # (+…Update+) or create (+…Add+) a resource.
    module Schema
      # Behavior of every value class.
      module Value
        # @param base [Class]
        # @return [void]
        # @api private
        def self.included(base) = base.extend(ClassMethods)

        # @param type [Class, Array<Class>, nil] a value class, a list of them, or nil for plain JSON
        # @param data [Object] the JSON of the bridge
        # @return [Object]
        # @api private
        def self.load(type, data)
          case type
          in [item] then data&.map { load(item, it) }
          in Class then data && type.from(data)
          else data
          end
        end

        # @param value [Object]
        # @return [Object] +value+ as JSON-ready data
        # @api private
        def self.dump(value)
          case value
          when Value then value.to_body
          when Array then value.map { dump(it) }
          else value
          end
        end

        # Class methods of the value classes.
        module ClassMethods
          # @return [Array<Symbol>] the members a value may leave out
          # @api private
          def optional_members = @optional_members || []

          # @return [Hash{Symbol=>Class, Array<Class>}] the members holding a value, or a list of them
          # @api private
          def nested_members = @nested_members || {}

          # Builds a value from the JSON of the bridge, ignoring the keys its class does not know.
          #
          # @param data [Hash{String=>Object}]
          # @return [Value]
          # @api public
          def from(data) = new(**members.to_h { [it, Value.load(nested_members[it], data[it.to_s])] })

          private

          # @param names [Array<Symbol>]
          # @return [void]
          # @api private
          def optional(*names)
            @optional_members = names
          end

          # @param types [Hash{Symbol=>Class, Array<Class>}]
          # @return [void]
          # @api private
          def nested(**types)
            @nested_members = types
          end
        end

        # @param fields [Hash{Symbol=>Object}] the members; an optional one left out is nil
        # @raise [ArgumentError] for an unknown member, or a missing one the class requires
        # @api public
        def initialize(**fields)
          value_class = self.class #: ClassMethods
          super(**value_class.optional_members.to_h { [it, nil] }, **fields)
        end

        # @return [Hash{Symbol=>Object}] the value as a JSON body, without its nil members
        # @api public
        def to_body = to_h.compact.transform_values { Value.dump(it) }
      end
    end
  end
end

require_relative 'schema/responses'
require_relative 'schema/updates'
require_relative 'schema/creates'
